<script setup>
import{computed}from'vue';import{ElRadioGroup,ElRadio,ElCheckboxGroup,ElCheckbox}from'element-plus';import{responseType}from'@/services/education.js';import Input from'@/components/app/Input.vue';import Textarea from'@/components/app/Textarea.vue';
defineOptions({inheritAttrs:false});const props=defineProps({question:{default:()=>({})},disabled:Boolean,readonly:Boolean,id:String,label:{default:'你的答案'}}),model=defineModel({default:''});const type=computed(()=>responseType(props.question));const multiple=computed({get:()=>String(model.value||'').split(',').filter(Boolean),set:value=>model.value=value.join(',')});
</script>
<template><ElRadioGroup v-if="['single_choice','true_false'].includes(type)" :id="id" v-model="model" class="answer-options" :disabled="disabled||readonly" :aria-label="label"><ElRadio v-for="item in type==='true_false'?[{id:'true',text:'正确'},{id:'false',text:'错误'}]:question.options||[]" :key="item.id" :value="item.id">{{item.id==='true'||item.id==='false'?'':item.id+'　'}}{{item.text}}</ElRadio></ElRadioGroup><ElCheckboxGroup v-else-if="type==='multiple_choice'" :id="id" v-model="multiple" class="answer-options" :disabled="disabled||readonly" :aria-label="label"><ElCheckbox v-for="item in question.options||[]" :key="item.id" :value="item.id">{{item.id}}　{{item.text}}</ElCheckbox></ElCheckboxGroup><Textarea v-else-if="['short_answer','essay','proof','reading','writing','translation','experiment','programming'].includes(type)" :id="id" v-model="model" :aria-label="label" :disabled="disabled" :readonly="readonly" v-bind="$attrs"/><Input v-else :id="id" v-model="model" :aria-label="label" :disabled="disabled" :readonly="readonly" v-bind="$attrs"/></template>
